def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = max(range(10), key=lambda color: sum(row.count(color) for row in grid))

    # Scan each diagonal, extending a contiguous non-background group when
    # it contains a repeated adjacent color. The endpoint colors continue out.
    for dr, dc in ((1, 1), (1, -1)):
        starts = []
        for c in range(w):
            starts.append((0, c))
        for r in range(1, h):
            starts.append((r, 0 if dc == 1 else w - 1))

        for sr, sc in starts:
            coords = []
            r, c = sr, sc
            while 0 <= r < h and 0 <= c < w:
                coords.append((r, c))
                r += dr
                c += dc
            i = 0
            while i < len(coords):
                r, c = coords[i]
                if grid[r][c] == background:
                    i += 1
                    continue
                j = i + 1
                while j < len(coords) and grid[coords[j][0]][coords[j][1]] != background:
                    j += 1
                colors = [grid[rr][cc] for rr, cc in coords[i:j]]
                first_run = 1
                while first_run < len(colors) and colors[first_run] == colors[0]:
                    first_run += 1
                last_run = 1
                while last_run < len(colors) and colors[-1 - last_run] == colors[-1]:
                    last_run += 1
                if first_run >= 2:
                    for k in range(i):
                        rr, cc = coords[k]
                        out[rr][cc] = colors[0]
                if last_run >= 2:
                    for k in range(j, len(coords)):
                        rr, cc = coords[k]
                        out[rr][cc] = colors[-1]
                i = j
    return out
